{
  "schema": "redline.threatmodel.v1",
  "issueKey": "EVAL-08",
  "sketch": {
    "components": ["Admin UI", "Customer session service", "Authentication service", "Support role management", "Session store"],
    "dataStores": ["User database", "Session store", "Audit logs"],
    "externalServices": [],
    "trustBoundaries": ["Admin to customer"],
    "dataClasses": ["pii"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "ElevationOfPrivilege",
      "title": "Overly broad support role enables insider abuse of impersonation",
      "scenario": "Any employee with the support role can impersonate any customer. If the support role is assigned too broadly (e.g., to all customer service, QA, or operations staff), many employees have unrestricted access to all customer accounts without business need. An insider or compromised account can read sensitive data, modify settings, or perform actions as any customer.",
      "component": "Support role management",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "It is available to every employee with the support role."
        }
      ],
      "asvs": ["V4.1.3"],
      "cwe": ["CWE-285"],
      "plainLanguage": "Every support employee can log in as any customer, even if they don't need that access for their job",
      "requirement": {
        "title": "Restrict impersonation to justified cases",
        "given": "an employee with support role needs to impersonate a customer",
        "when": "they attempt impersonation",
        "then": "the system requires a business justification (e.g., ticket ID) and restricts impersonation to employees who need it for their role"
      }
    },
    {
      "stride": "Spoofing",
      "title": "No additional verification before impersonation enables credential theft impact",
      "scenario": "If an attacker steals an admin's credentials (via phishing, session hijacking, or malware), they can immediately impersonate any customer without additional verification. The attacker accesses customer data, modifies accounts, or performs fraudulent transactions. Without MFA or approval workflows, a single compromised credential gives full impersonation access.",
      "component": "Authentication service",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "Support admins can click \"log in as customer\" to see exactly what a customer sees."
        }
      ],
      "asvs": ["V2.1.1"],
      "cwe": ["CWE-306"],
      "plainLanguage": "If someone steals an admin password, they can immediately impersonate any customer with one click",
      "requirement": {
        "title": "Require additional verification for impersonation",
        "given": "an admin attempts to impersonate a customer",
        "when": "they click 'log in as customer'",
        "then": "the system requires MFA re-authentication and records a business justification before granting access"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Missing audit trail for impersonation actions",
      "scenario": "The design does not mention audit logging. If impersonation sessions and actions taken during them are not logged, an admin can deny unauthorized actions, data access, or policy violations. During an incident investigation or compliance audit, there is no evidence of who impersonated whom, when, or what they did.",
      "component": "Customer session service",
      "likelihood": 5,
      "impact": 3,
      "evidence": [
        {
          "quote": "The feature issues a customer session to the admin."
        }
      ],
      "asvs": ["V7.1.1", "V7.2.1"],
      "cwe": ["CWE-778"],
      "plainLanguage": "Admins can deny what they did while logged in as a customer because the system doesn't record it",
      "requirement": {
        "title": "Log all impersonation activity",
        "given": "an admin impersonates a customer",
        "when": "impersonation starts, ends, or the admin performs any action",
        "then": "the system logs the admin identity, customer identity, timestamp, action, and reason in a tamper-evident audit log"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Impersonation session tokens could leak and be reused",
      "scenario": "If impersonation session tokens are issued as standard customer sessions without special marking or additional protection, they could be stolen via XSS, logged in diagnostics, or leaked through referrer headers. An attacker with the token can impersonate the customer without admin credentials. If tokens are long-lived or not bound to the admin's session, the risk is higher.",
      "component": "Session store",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "The feature issues a customer session to the admin."
        }
      ],
      "asvs": ["V3.2.2", "V3.2.3"],
      "cwe": ["CWE-384"],
      "plainLanguage": "If the impersonation session token leaks, someone else can use it to access the customer's account",
      "requirement": {
        "title": "Bind impersonation sessions to admin session",
        "given": "an admin has an impersonation session",
        "when": "the admin's own session expires or is terminated",
        "then": "the system also terminates the impersonation session immediately"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Admins access all customer data without consent or notification",
      "scenario": "Admins can view all customer data, including PII, financial information, messages, and usage history. The design does not mention notifying customers when they are being impersonated. Customers have no visibility into who accessed their account or why. This violates privacy expectations and may breach GDPR or other regulations requiring transparency about data access.",
      "component": "Customer session service",
      "likelihood": 5,
      "impact": 3,
      "evidence": [
        {
          "quote": "Support admins can click \"log in as customer\" to see exactly what a customer sees."
        }
      ],
      "asvs": ["V4.1.1"],
      "cwe": ["CWE-284"],
      "plainLanguage": "Customers don't know when support staff are looking at their account and personal information",
      "requirement": {
        "title": "Notify customers of impersonation",
        "given": "an admin impersonates a customer",
        "when": "impersonation begins",
        "then": "the system sends a notification to the customer via email or in-app message with admin identity, timestamp, and reason"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Unbounded impersonation session lifetime enables session hijacking",
      "scenario": "The design does not specify time limits for impersonation sessions. If a session remains active indefinitely, an admin could leave their workstation unlocked or their device could be stolen, allowing an attacker to continue using the impersonation session. Long-lived sessions also increase the window for session token theft via XSS or network interception.",
      "component": "Session store",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "The feature issues a customer session to the admin."
        }
      ],
      "asvs": ["V3.2.1"],
      "cwe": ["CWE-613"],
      "plainLanguage": "An impersonation session could stay active forever, letting someone else use it if the admin's device is stolen",
      "requirement": {
        "title": "Expire impersonation sessions automatically",
        "given": "an admin has an active impersonation session",
        "when": "a configured time limit expires (e.g., 1 hour) or the admin logs out",
        "then": "the system terminates the impersonation session and requires re-authentication to start a new one"
      }
    },
    {
      "stride": "Tampering",
      "title": "Admins can modify customer data while impersonating without safeguards",
      "scenario": "While impersonating a customer, an admin can perform any action the customer can, including modifying profile data, settings, or business-critical records. If the design does not restrict destructive actions during impersonation, an admin (whether malicious or making an error) could delete data, change payment settings, or alter security configurations. The customer may not know these changes were made by an admin.",
      "component": "Customer session service",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "Support admins can click \"log in as customer\" to see exactly what a customer sees."
        }
      ],
      "asvs": ["V4.1.1"],
      "cwe": ["CWE-284"],
      "plainLanguage": "Admins can change or delete a customer's data while impersonating them, and the customer won't know who did it",
      "requirement": {
        "title": "Restrict write actions during impersonation",
        "given": "an admin is impersonating a customer",
        "when": "they attempt to modify or delete data",
        "then": "the system requires explicit confirmation, logs the action with justification, and optionally restricts high-risk actions to read-only unless approved"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "No approval workflow enables unauthorized impersonation",
      "scenario": "Any employee with the support role can immediately impersonate any customer without approval from a manager or security team. This lack of oversight allows an insider to impersonate VIP customers, executives, or compliance-sensitive accounts for unauthorized purposes. The lack of a waiting period or approval step removes a key control against abuse.",
      "component": "Support role management",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "It is available to every employee with the support role."
        }
      ],
      "asvs": ["V4.1.3"],
      "cwe": ["CWE-285"],
      "plainLanguage": "Support staff can impersonate any customer instantly without asking permission from a manager",
      "requirement": {
        "title": "Require approval for sensitive impersonations",
        "given": "an admin attempts to impersonate a VIP, privileged, or high-value customer",
        "when": "they initiate impersonation",
        "then": "the system requires approval from a manager or security team before granting access"
      }
    }
  ]
}
